"use client"

import * as React from "react"
import type { ReactTable, Row, RowData } from "@tanstack/react-table"
import { cn } from "cn"

import { Skeleton } from "@/components/ui/skeleton"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import type { DataTableFeatures } from "./features"

export type DataTableStatus = "ready" | "loading" | "error"

type DataTableProps<TData extends RowData> = {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  table: ReactTable<DataTableFeatures, TData, any>
  /** Accessible name of the table, read by screen readers. */
  caption: string
  status?: DataTableStatus
  /** Shown when there are no rows (use <DataTableEmpty />). */
  empty?: React.ReactNode
  /** Shown when status is "error" (use <ErrorState />). */
  error?: React.ReactNode
  /** Skeleton rows while loading; match the page size to avoid layout shift. */
  loadingRows?: number
  /** Row tap → detail. Clicks on buttons, links and checkboxes inside the row are ignored. */
  onRowClick?: (row: Row<DataTableFeatures, TData>) => void
  className?: string
}

const INTERACTIVE = "button, a, input, label, [role=checkbox], [role=menuitem]"

function DataTable<TData extends RowData>({
  table,
  caption,
  status = "ready",
  empty,
  error,
  loadingRows = 10,
  onRowClick,
  className,
}: DataTableProps<TData>) {
  const columns = table.getVisibleLeafColumns()
  const rows = table.getRowModel().rows

  return (
    <div
      data-slot="data-table"
      className={cn("overflow-hidden rounded-xl border border-border bg-card", className)}
    >
      <Table aria-busy={status === "loading"}>
        <caption className="sr-only">{caption}</caption>
        <TableHeader className="sticky top-0 z-10">
          {table.getHeaderGroups().map((group) => (
            <TableRow key={group.id}>
              {group.headers.map((header) => {
                const meta = header.column.columnDef.meta
                const sorted = header.column.getIsSorted()
                return (
                  <TableHead
                    key={header.id}
                    aria-sort={
                      sorted === "asc" ? "ascending" : sorted === "desc" ? "descending" : header.column.getCanSort() ? "none" : undefined
                    }
                    className={cn(
                      meta?.align === "right" && "text-right",
                      meta?.sticky && "sticky left-0 z-10 bg-secondary"
                    )}
                  >
                    {header.isPlaceholder ? null : <table.FlexRender header={header} />}
                  </TableHead>
                )
              })}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {status === "loading" &&
            Array.from({ length: loadingRows }, (_, i) => (
              <TableRow key={`skeleton-${i}`} className="hover:bg-transparent">
                {columns.map((column) => (
                  <TableCell key={column.id}>
                    <Skeleton className="h-4 w-full max-w-32" />
                  </TableCell>
                ))}
              </TableRow>
            ))}

          {status === "error" && (
            <TableRow className="hover:bg-transparent">
              <TableCell colSpan={columns.length} className="h-auto p-0 whitespace-normal">
                {error}
              </TableCell>
            </TableRow>
          )}

          {status === "ready" && rows.length === 0 && (
            <TableRow className="hover:bg-transparent">
              <TableCell colSpan={columns.length} className="h-auto p-0 whitespace-normal">
                {empty}
              </TableCell>
            </TableRow>
          )}

          {status === "ready" &&
            rows.map((row) => (
              <TableRow
                key={row.id}
                data-state={row.getIsSelected() ? "selected" : undefined}
                className={cn(onRowClick && "cursor-pointer")}
                onClick={
                  onRowClick
                    ? (event) => {
                        if ((event.target as HTMLElement).closest(INTERACTIVE)) return
                        onRowClick(row)
                      }
                    : undefined
                }
              >
                {row.getVisibleCells().map((cell) => {
                  const meta = cell.column.columnDef.meta
                  return (
                    <TableCell
                      key={cell.id}
                      className={cn(
                        meta?.align === "right" && "text-right",
                        meta?.sticky && "sticky left-0 bg-inherit"
                      )}
                    >
                      <table.FlexRender cell={cell} />
                    </TableCell>
                  )
                })}
              </TableRow>
            ))}
        </TableBody>
      </Table>
    </div>
  )
}

export { DataTable }

"use client"

import type { Column, RowData } from "@tanstack/react-table"
import { ArrowDownIcon, ArrowUpIcon, ChevronsUpDownIcon } from "lucide-react"
import { cn } from "cn"

import { Button } from "@/components/ui/button"
import type { DataTableFeatures } from "./features"

type DataTableColumnHeaderProps<TData extends RowData, TValue> = {
  column: Column<DataTableFeatures, TData, TValue>
  title: string
  className?: string
}

/**
 * Sortable header. Each tap moves to the next order TanStack defines for the column:
 * text starts ascending (ก→ฮ, A→Z); numbers and dates start descending (largest/newest first).
 * The <th> carries aria-sort (set by DataTable); the button says what the next tap does.
 */
function DataTableColumnHeader<TData extends RowData, TValue>({
  column,
  title,
  className,
}: DataTableColumnHeaderProps<TData, TValue>) {
  if (!column.getCanSort()) return <span className={className}>{title}</span>

  const sorted = column.getIsSorted()
  const Icon = sorted === "asc" ? ArrowUpIcon : sorted === "desc" ? ArrowDownIcon : ChevronsUpDownIcon
  const nextOrder = column.getNextSortingOrder()
  const next = nextOrder === "asc" ? "เรียงจากน้อยไปมาก" : nextOrder === "desc" ? "เรียงจากมากไปน้อย" : "ยกเลิกการเรียง"

  return (
    <Button
      variant="ghost"
      size="sm"
      className={cn(
        "-mx-3 h-control-sm px-3 font-medium text-foreground-secondary data-[sorted=true]:text-primary",
        column.columnDef.meta?.align === "right" && "flex-row-reverse",
        className
      )}
      data-sorted={Boolean(sorted)}
      aria-label={`${title}: ${next}`}
      onClick={column.getToggleSortingHandler()}
    >
      {title}
      <Icon data-icon="inline-end" className={cn("size-3.5", !sorted && "opacity-50")} aria-hidden />
    </Button>
  )
}

export { DataTableColumnHeader }

"use client"

import type { Column, RowData } from "@tanstack/react-table"
import { CheckIcon, PlusCircleIcon } from "lucide-react"
import { cn } from "cn"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from "@/components/ui/command"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { Separator } from "@/components/ui/separator"
import type { DataTableFeatures } from "./features"

export type FacetOption = { label: string; value: string; count?: number }

type DataTableFacetedFilterProps<TData extends RowData, TValue> = {
  column?: Column<DataTableFeatures, TData, TValue>
  title: string
  options: FacetOption[]
}

/** Multi-select filter for enum columns (status, channel). Use filterFn "arrIncludesSome". */
function DataTableFacetedFilter<TData extends RowData, TValue>({
  column,
  title,
  options,
}: DataTableFacetedFilterProps<TData, TValue>) {
  const selected = new Set((column?.getFilterValue() as string[] | undefined) ?? [])

  function toggle(value: string) {
    const next = new Set(selected)
    if (next.has(value)) next.delete(value)
    else next.add(value)
    column?.setFilterValue(next.size ? [...next] : undefined)
  }

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button variant="outline" className="border-dashed text-foreground">
          <PlusCircleIcon data-icon="inline-start" />
          {title}
          {selected.size > 0 && (
            <>
              <Separator orientation="vertical" className="mx-1 h-4" />
              {selected.size > 2 ? (
                <Badge variant="accent">เลือก {selected.size}</Badge>
              ) : (
                options
                  .filter((o) => selected.has(o.value))
                  .map((o) => (
                    <Badge key={o.value} variant="accent">
                      {o.label}
                    </Badge>
                  ))
              )}
            </>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-64 p-0" align="start">
        <Command>
          <CommandInput placeholder={`ค้นหา${title}`} />
          <CommandList>
            <CommandEmpty>ไม่พบตัวเลือก</CommandEmpty>
            <CommandGroup>
              {options.map((option) => {
                const isSelected = selected.has(option.value)
                return (
                  <CommandItem key={option.value} onSelect={() => toggle(option.value)} aria-selected={isSelected}>
                    <span
                      aria-hidden
                      className={cn(
                        "flex size-4 items-center justify-center rounded-sm border border-input",
                        isSelected && "border-primary bg-primary text-primary-foreground"
                      )}
                    >
                      {isSelected && <CheckIcon className="size-3" />}
                    </span>
                    <span className="flex-1">{option.label}</span>
                    {option.count !== undefined && (
                      <span className="font-mono text-xs text-muted-foreground tabular-nums">{option.count}</span>
                    )}
                  </CommandItem>
                )
              })}
            </CommandGroup>
            {selected.size > 0 && (
              <>
                <CommandSeparator />
                <CommandGroup>
                  <CommandItem onSelect={() => column?.setFilterValue(undefined)} className="justify-center">
                    ล้างตัวกรองนี้
                  </CommandItem>
                </CommandGroup>
              </>
            )}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

export { DataTableFacetedFilter }

"use client"

import * as React from "react"
import type { ReactTable, RowData } from "@tanstack/react-table"
import { Columns3Icon, SearchIcon, XIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/components/ui/input-group"
import type { DataTableFeatures } from "./features"

type DataTableToolbarProps<TData extends RowData> = {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  table: ReactTable<DataTableFeatures, TData, any>
  searchPlaceholder?: string
  /** Debounce for the search box (ms). Server-side search should keep ≥ 300. */
  debounce?: number
  /** <DataTableFacetedFilter /> elements. */
  filters?: React.ReactNode
  /** Actions on the right, e.g. Export. */
  actions?: React.ReactNode
}

function DataTableToolbar<TData extends RowData>({
  table,
  searchPlaceholder = "ค้นหา",
  debounce = 300,
  filters,
  actions,
}: DataTableToolbarProps<TData>) {
  const globalFilter = (table.state.globalFilter as string | undefined) ?? ""
  const [search, setSearch] = React.useState(globalFilter)
  const isFiltered = table.state.columnFilters.length > 0 || globalFilter !== ""

  React.useEffect(() => {
    if (search === globalFilter) return
    const timer = setTimeout(() => table.setGlobalFilter(search || undefined), debounce)
    return () => clearTimeout(timer)
  }, [search, globalFilter, debounce, table])

  function reset() {
    setSearch("")
    table.resetColumnFilters()
    table.setGlobalFilter(undefined)
  }

  return (
    <div data-slot="data-table-toolbar" className="flex flex-wrap items-center gap-2">
      <InputGroup className="w-full sm:w-72">
        <InputGroupAddon>
          <SearchIcon />
        </InputGroupAddon>
        <InputGroupInput
          type="search"
          aria-label={searchPlaceholder}
          placeholder={searchPlaceholder}
          value={search}
          onChange={(event) => setSearch(event.target.value)}
        />
        {search && (
          <InputGroupAddon align="inline-end">
            <InputGroupButton size="icon-xs" aria-label="ล้างคำค้นหา" onClick={() => setSearch("")}>
              <XIcon />
            </InputGroupButton>
          </InputGroupAddon>
        )}
      </InputGroup>
      {filters}
      {isFiltered && (
        <Button variant="ghost" onClick={reset}>
          ล้างตัวกรอง
          <XIcon data-icon="inline-end" />
        </Button>
      )}
      <div className="ml-auto flex items-center gap-2">
        {actions}
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline">
              <Columns3Icon data-icon="inline-start" />
              คอลัมน์
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-52">
            <DropdownMenuGroup>
              <DropdownMenuLabel>แสดงคอลัมน์</DropdownMenuLabel>
              <DropdownMenuSeparator />
              {table
                .getAllLeafColumns()
                .filter((column) => column.getCanHide())
                .map((column) => (
                  <DropdownMenuCheckboxItem
                    key={column.id}
                    checked={column.getIsVisible()}
                    onCheckedChange={(value) => column.toggleVisibility(!!value)}
                    onSelect={(event) => event.preventDefault()}
                  >
                    {column.columnDef.meta?.label ?? column.id}
                  </DropdownMenuCheckboxItem>
                ))}
            </DropdownMenuGroup>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </div>
  )
}

export { DataTableToolbar }
